contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address token, address[] memory tos, uint[] memory vs, uint amount) public payable {
        require(tos.length > 0);
        require(vs.length > 0);
        require(tos.length == vs.length);
        require(amount > 0);
        require(address(this).balance >= amount);

        // Rule 1: sending value must revert (transfer is not payable)
        bool revertedWithValue;
        try c.transfer{value: amount}(token, tos, vs) { revertedWithValue = false; }
        catch { revertedWithValue = true; }
        require(revertedWithValue);

        // Rule 2: without value, transfer either reverts (a sub-call fails) or returns true
        bool reverted;
        bool ret = false;
        try c.transfer(token, tos, vs) returns (bool r) { reverted = false; ret = r; }
        catch { reverted = true; }

        assert(reverted || ret);
    }

    receive() external payable {}
}

contract InvMutTest {
