        require(token != address(c));
        require(tos.length > 0);
        require(vs.length > 0);
        require(tos.length == vs.length);

        uint balCBefore = address(c).balance;
        uint balTestBefore = address(this).balance;

        bool ok = c.transfer(token, tos, vs);

        assert(ok && address(c).balance == balCBefore && address(this).balance == balTestBefore);
    }

    fallback() external payable {}
    receive() external payable {}
}
